import"./hoisted.CX6vcqWe.js";document.addEventListener("DOMContentLoaded",()=>{const c=document.querySelectorAll(".filter-btn"),o=document.querySelectorAll(".project-item");c.forEach(t=>{t.addEventListener("click",()=>{c.forEach(e=>e.classList.remove("active")),t.classList.add("active");const l=t.getAttribute("data-filter");o.forEach(e=>{l==="all"||e.getAttribute("data-category").includes(l)?e.style.display="block":e.style.display="none"})})})});
